import {createRequire} from 'node:module';import {readFile,mkdir} from 'node:fs/promises';import assert from 'node:assert/strict';import http from 'node:http';import path from 'node:path';
const {chromium}=createRequire(import.meta.url)('playwright');const root=path.resolve('extension');const files=['dashboard.html','app.js','model.js','style.css','icon.png','fonts/Montserrat.ttf','fonts/LibreCaslonText-Regular.ttf','popup.html','popup.js','background.js'];for(const file of files)await readFile(path.join(root,file));
const server=http.createServer(async(req,res)=>{try{const file=path.resolve(root,'.'+new URL(req.url,'http://localhost').pathname);if(!file.startsWith(root+path.sep))throw Error();let body=await readFile(file);const ext=path.extname(file);res.setHeader('Content-Type',({'.js':'text/javascript','.html':'text/html','.css':'text/css','.ttf':'font/ttf','.png':'image/png'})[ext]||'application/octet-stream');if(file.endsWith('/app.js'))body=body.toString().replace("location.protocol==='chrome-extension:'&&Boolean(globalThis.chrome?.runtime?.id)","Boolean(globalThis.chrome?.runtime?.id)");res.end(body);}catch{res.writeHead(404);res.end();}});await new Promise(r=>server.listen(4174,'127.0.0.1',r));
const browser=await chromium.launch({executablePath:'/usr/bin/chromium',headless:true,args:['--no-sandbox']});
try{const page=await browser.newPage({viewport:{width:1440,height:1024}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
await page.addInitScript(()=>{const listeners=[];const stored={};window.__afmdFixture={put:async(id,value)=>{stored[id]=value;listeners.forEach(fn=>fn());}};window.chrome={runtime:{id:'afmd-fixture',getURL:p=>p},storage:{local:{get:async()=>stored},onChanged:{addListener:fn=>listeners.push(fn)}}};});
await page.goto('http://127.0.0.1:4174/dashboard.html');await page.getByRole('heading',{name:'Minhas transcrições',exact:true}).waitFor();await page.getByRole('button',{name:'Clientes',exact:true}).click();await page.getByRole('button',{name:'Novo cliente'}).click();await page.locator('#client-name').fill('Clínica Horizonte');await page.getByRole('button',{name:'Salvar cliente'}).click();await page.getByRole('button',{name:'Minhas transcrições',exact:true}).click();
const capture={format:'afmd-meet-v1',title:'Alinhamento Clínica Horizonte',started:'2026-11-01T14:00:00Z',running:false,segments:[{time:'00:12',speaker:'Ana',text:'Precisamos revisar a proposta até sexta.'},{time:'00:24',speaker:'Mariana',text:'Eu envio o material para a equipe.'}]};
await page.evaluate(c=>window.__afmdFixture.put('afmd-meet-fixture',c),capture);await page.getByRole('heading',{name:capture.title,exact:true}).waitFor();assert.equal(await page.locator('#assign-client option:checked').textContent(),'Clínica Horizonte');assert.match(await page.locator('.document').textContent(),/00:24.*Mariana/);await page.evaluate(c=>window.__afmdFixture.put('afmd-meet-fixture',c),capture);await page.waitForTimeout(100);assert.equal(await page.locator('.meeting').count(),1);
await page.getByRole('button',{name:'Resumo',exact:true}).click();await page.getByRole('button',{name:'Gerar resumo',exact:true}).click();await page.getByRole('status').filter({hasText:'IA ainda não conectada nesta extensão'}).waitFor();await page.getByRole('button',{name:'Transcrição',exact:true}).click();await page.locator('#notice').evaluate(e=>e.textContent='');await page.screenshot({path:'test-results/extension-dashboard.png',fullPage:true});await page.getByRole('button',{name:'Clientes',exact:true}).click();await page.screenshot({path:'test-results/extension-clients.png',fullPage:true});
const popup=await browser.newPage();await popup.addInitScript(()=>{window.chrome={runtime:{getURL:p=>'chrome-extension://fixture/'+p},tabs:{query:async(q,cb)=>cb([{url:'https://example.org'}]),create:arg=>window.__opened=arg}};});await popup.goto('http://127.0.0.1:4174/popup.html');await popup.getByRole('button',{name:'Abrir painel AFMD'}).click();assert.equal(await popup.evaluate(()=>window.__opened.url),'chrome-extension://fixture/dashboard.html');assert.deepEqual(errors,[]);console.log('PASS: conteúdo do ZIP, renderização do painel embarcado, fontes locais, importação automática com Chrome Storage simulado, deduplicação, associação, estado de IA desconectada e botão Abrir painel. Instalação MV3 real bloqueada pela política do navegador gerenciado.');
}finally{await browser.close();await new Promise(r=>server.close(r));}
